/**
 * Install typed mock handlers for the generated commands.
 *
 * Handlers are installed through `@tauri-apps/api/mocks`'s `mockIPC`, so the application
 * under test keeps importing the real `commands` object and still runs the argument and
 * result transforms around each call.
 *
 * A handler receives the command's arguments and returns its success value; throw (or
 * return a rejected promise) to make the command fail. A command with no handler rejects
 * with an error rather than resolving `undefined`, so a test can't pass by accident.
 *
 * Tauri's event mocking is enabled as part of the install (`shouldMockEvents`), so
 * `events` keeps working under test without a second installer fighting this one. Note
 * that Tauri's own mock does not implement `emitTo`, which resolves without reaching any
 * listener. Call `clearMocks` from `@tauri-apps/api/mocks` between tests.
 */
export function mockCommands(
  handlers: Partial<MockCommandHandlers> = {},
): void {
  // A copy with no prototype, so a command named after an `Object.prototype` member
  // (`toString`, `constructor`, …) reports that it is unregistered instead of calling
  // whatever the prototype happens to provide.
  const mockHandlers: Partial<MockCommandHandlers> = Object.create(null);
  Object.assign(mockHandlers, handlers);
  return __TAURI_MOCK_IPC(
    (cmd, args) => {
      switch (cmd) {
        case "app_version":
          return mockCommandHandler(
            mockHandlers.appVersion,
            "app_version",
            args,
          );
        case "get_settings":
          return mockCommandHandler(
            mockHandlers.getSettings,
            "get_settings",
            args,
          );
        case "set_order_permission":
          return mockCommandHandler(
            mockHandlers.setOrderPermission,
            "set_order_permission",
            args,
          );
        case "send_chat_message":
          return mockCommandHandler(
            mockHandlers.sendChatMessage,
            "send_chat_message",
            args,
          );
        case "get_chat_history":
          return mockCommandHandler(
            mockHandlers.getChatHistory,
            "get_chat_history",
            args,
          );
        case "resubscribe_chat_turn":
          return mockCommandHandler(
            mockHandlers.resubscribeChatTurn,
            "resubscribe_chat_turn",
            args,
          );
        case "cancel_chat_turn":
          return mockCommandHandler(
            mockHandlers.cancelChatTurn,
            "cancel_chat_turn",
            args,
          );
        case "open_external":
          return mockCommandHandler(
            mockHandlers.openExternal,
            "open_external",
            args,
          );
        case "request_order_approval":
          return mockCommandHandler(
            mockHandlers.requestOrderApproval,
            "request_order_approval",
            args,
          );
        case "get_briefings":
          return mockCommandHandler(
            mockHandlers.getBriefings,
            "get_briefings",
            args,
          );
        case "get_portfolio":
          return mockCommandHandler(
            mockHandlers.getPortfolio,
            "get_portfolio",
            args,
          );
        case "get_allocation":
          return mockCommandHandler(
            mockHandlers.getAllocation,
            "get_allocation",
            args,
          );
        case "get_job_schedules":
          return mockCommandHandler(
            mockHandlers.getJobSchedules,
            "get_job_schedules",
            args,
          );
        case "set_job_schedule":
          return mockCommandHandler(
            mockHandlers.setJobSchedule,
            "set_job_schedule",
            args,
          );
        case "get_public_ip":
          return mockCommandHandler(
            mockHandlers.getPublicIp,
            "get_public_ip",
            args,
          );
        case "copy_text":
          return mockCommandHandler(mockHandlers.copyText, "copy_text", args);
        case "check_toss_connection":
          return mockCommandHandler(
            mockHandlers.checkTossConnection,
            "check_toss_connection",
            args,
          );
        case "submit_toss_keys":
          return mockCommandHandler(
            mockHandlers.submitTossKeys,
            "submit_toss_keys",
            args,
          );
        case "get_update_status":
          return mockCommandHandler(
            mockHandlers.getUpdateStatus,
            "get_update_status",
            args,
          );
        case "restart_to_update":
          return mockCommandHandler(
            mockHandlers.restartToUpdate,
            "restart_to_update",
            args,
          );
        case "get_risk_settings":
          return mockCommandHandler(
            mockHandlers.getRiskSettings,
            "get_risk_settings",
            args,
          );
        case "save_investor_profile":
          return mockCommandHandler(
            mockHandlers.saveInvestorProfile,
            "save_investor_profile",
            args,
          );
        case "save_order_settings":
          return mockCommandHandler(
            mockHandlers.saveOrderSettings,
            "save_order_settings",
            args,
          );
        default:
          throw new Error(`No mock handler registered for command '${cmd}'`);
      }
    },
    { shouldMockEvents: true },
  );
}

function mockCommandHandler(
  handler: ((args: any) => unknown) | undefined,
  name: string,
  args: unknown,
): unknown {
  if (handler === undefined)
    throw new Error(`No mock handler registered for command '${name}'`);
  return handler(args);
}
